```ts
import type { Camera } from "@babylonjs/lite";
import {
  getViewMatrix,
  getViewProjectionMatrix,
  getEffectiveAspectRatio,
  getCameraPosition,
  resolveCameraViewport,
  projectWorldToScreen,
} from "@babylonjs/lite";

export function labelPosition(
  camera: Camera,
  canvas: HTMLCanvasElement,
  point: { x: number; y: number; z: number },
): { x: number; y: number; visible: boolean } {
  const backingWidth = canvas.width;
  const backingHeight = canvas.height;
  const cssWidth = canvas.clientWidth || backingWidth;
  const cssHeight = canvas.clientHeight || backingHeight;

  // Resolve the pixel viewport (handles camera.viewport, clamps to canvas).
  const viewport = resolveCameraViewport(camera, backingWidth, backingHeight);

  // Aspect ratio matching what is actually rendered (note 36).
  const aspect = getEffectiveAspectRatio(camera, viewport.width, viewport.height);

  // Get view and view-projection matrices. These return the camera's own
  // cache objects (note 35), so we must use them immediately.
  const view = getViewMatrix(camera);
  const viewProjection = getViewProjectionMatrix(camera, aspect);

  // Build options for projectWorldToScreen.
  const options = {
    viewport,
    backingWidth,
    backingHeight,
    cssWidth,
    cssHeight,
  };

  // If the camera uses a floating origin, we must supply the world origin
  // (note 63).
  if (camera._useFloatingOrigin) {
    options.worldOrigin = getCameraPosition(camera);
  }

  const result = projectWorldToScreen(point, view, viewProjection, options);

  // Visibility: in front of the camera AND inside the picture.
  // Points past the far plane but in-frame are still visible (problem spec).
  // Points behind the camera are never visible.
  const visible = !result.behindCamera && !result.offscreen;

  return {
    x: result.cssX,
    y: result.cssY,
    visible,
  };
}
```

